const items = $input.all();
const DOMINIO_PROPRIO = 'ateliersenzapari.com.br';
const resultado = [];

for (const item of items) {
  const json = item.json;
  const remetente = (json.from && json.from.value && json.from.value[0] && json.from.value[0].address) || json.from || '';
  const remetenteNome = (json.from && json.from.value && json.from.value[0] && json.from.value[0].name) || '';
  const destinatarios = (json.to && json.to.value) ? json.to.value.map((v) => (v.address || '').toLowerCase()) : [];
  const paraTexto = destinatarios.join(' ');
  const assunto = json.subject || '';
  const corpo = json.textPlain || json.text || '';

  // Ignora e-mails internos (nossos proprios encaminhamentos/rascunhos) para nao criar loop
  if (remetente.toLowerCase().includes(DOMINIO_PROPRIO)) continue;
  // financeiro@ e tratado manualmente, nao por IA
  if (paraTexto.includes('financeiro@')) continue;
  // So processa o que foi endereçado a vendas@ ou contato@
  if (!paraTexto.includes('vendas@') && !paraTexto.includes('contato@')) continue;

  resultado.push({
    json: {
      remetente,
      remetenteNome,
      destinatario: destinatarios[0] || 'contato@ateliersenzapari.com.br',
      assunto,
      corpo
    }
  });
}

return resultado;

const resposta = $input.first().json;
const dados = $('Extrair Dados').first().json;
const config = $('Config').first().json;

const texto = (resposta.content && resposta.content[0] && resposta.content[0].text) || '';

return [{
  json: {
    ...dados,
    respostaIA: texto,
    envioAutomatico: config.envioAutomatico,
    emailAprovacao: config.emailAprovacao
  }
}];

